function candidatePublicOriginalRows(day, contract) {
  if (day.schema_version === "dc20_candidate_formal_profit_day_v1") {
    executableProfitExpect(!["original_rows","eligibility","eligibility_policy_id","original_candidate_count"].some(k=>k in day), "旧版不能混入逐股资格字段");
    return day.rows;
  }
  executableProfitExpect(day.schema_version === "dc20_candidate_formal_profit_day_v2_eligible"
    && day.eligibility_policy_id === "dc20_individual_observed_window_eligibility_20260922_v2"
    && Array.isArray(day.original_rows) && Array.isArray(day.eligibility)
    && day.original_rows.length === contract.rows.length && day.original_candidate_count === contract.rows.length
    && day.eligibility.length === contract.rows.length, "逐股资格原名单缺失");
  const allowed=new Set();
  contract.rows.forEach((original,i)=>{
    const row=day.original_rows[i], e=day.eligibility[i];
    executableProfitExpect(exactObjectKeys(row,["ts_code","promotion_rank","board_stage","name","industry","candidate_rank","candidate_score"])
      && ["ts_code","promotion_rank","name","industry"].every(k=>row[k]===original[k])
      && row.promotion_rank===i+1 && row.board_stage===(original.stage_transition==="2→3"?2:3)
      && row.candidate_rank===null && row.candidate_score===null, "原晋级名单身份改变");
    executableProfitExpect(exactObjectKeys(e,["ts_code","promotion_rank","eligible","reason","observed_bar_count","required_observed_bar_count"])
      && e.ts_code===row.ts_code && e.promotion_rank===row.promotion_rank && typeof e.eligible==="boolean"
      && Number.isInteger(e.observed_bar_count) && e.observed_bar_count>=0 && e.observed_bar_count<=21
      && e.required_observed_bar_count===21, "逐股资格诊断无效");
    if(e.eligible) {
      executableProfitExpect(e.reason===null && e.observed_bar_count===21,"可评分股票历史不足");allowed.add(e.ts_code);
    } else executableProfitExpect(["INSUFFICIENT_OBSERVED_HISTORY","MISSING_D_OBSERVATION"].includes(e.reason)
      && (e.reason!=="INSUFFICIENT_OBSERVED_HISTORY" || e.observed_bar_count<21),"排除原因无效");
  });
  executableProfitExpect(Array.isArray(day.rows) && day.rows.length===allowed.size
    && new Set(day.rows.map(r=>r.ts_code)).size===allowed.size && day.rows.every(r=>allowed.has(r.ts_code)),"可评分股票集合不一致");
  return day.original_rows;
}

